import re,collections
lines=open('text.gcode').read().splitlines()
# find high-level Z moves G1 ... Z without E? parse all G1 with Z
zs=[]
for i,l in enumerate(lines):
    if l.startswith('G1') and ' Z' in l:
        m=re.search(r'Z([-+]?\d*\.?\d+)',l)
        if m: zs.append((i,float(m.group(1)),l))
# print max/min and distribution per 10000 lines
print('total z moves',len(zs),'min',min(z for _,z,_ in zs),'max',max(z for _,z,_ in zs))
for start in range(0,len(lines),10000):
    sub=[(i,z,l) for i,z,l in zs if start<=i<start+10000]
    if sub:
      print(start, 'n',len(sub),'zrange',min(z for _,z,_ in sub),max(z for _,z,_ in sub))
print('first zs')
for x in zs[:30]:print(x)
