import re
lines=open('text.gcode').read().splitlines()
a,b=15013,98472
# group by layer z: detect G1 Z... F720 layer start; collect points with E>0 and current x,y until next layer
layers=[]; curz=None; pts=[]; curx=cury=None
for i in range(a,b):
 l=lines[i]
 if l.startswith('G1'):
  mz=re.search(r' Z([-+]?\d*\.?\d+)',l)
  if mz:
   z=float(mz.group(1))
   if re.search(r'Z[-+]?\d*\.?\d+ F720',l):
    if curz is not None: layers.append((curz,pts))
    curz=z;pts=[]
  mx=re.search(r'X([-+]?\d*\.?\d+)',l); my=re.search(r'Y([-+]?\d*\.?\d+)',l)
  if mx: curx=float(mx.group(1))
  if my: cury=float(my.group(1))
  me=re.search(r'E([-+]?\d*\.?\d+)',l)
  if me and float(me.group(1))>0 and curx is not None and cury is not None:
   pts.append((curx,cury))
if curz is not None: layers.append((curz,pts))
# combine same z (multiple sublayers due travel)
from collections import defaultdict
d=defaultdict(list)
for z,p in layers:d[round(z,3)].extend(p)
for z in sorted(d):
 p=d[z]
 if p:
  xs=[x for x,y in p];ys=[y for x,y in p]
  print(f'{z:.2f} n={len(p):4d} bbox X {min(xs):.1f}-{max(xs):.1f} Y {min(ys):.1f}-{max(ys):.1f}')
